# -*- coding: utf-8 -*-
"""B3286 will: intention, modal grammar, determination and welcome."""
import json
from pathlib import Path
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
S=lambda w:'https://www.etymonline.com/word/'+w
O=lambda w:'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
K=lambda w:'https://en.wiktionary.org/wiki/'+w
W=[
E('will','/wɪl/；缩略 ’ll 常读 /l/','会、将；愿意；意志；遗嘱','“我愿意去做”很容易走到“我会去做”。这是理解 will 的好入口，但现代的 It will rain 只是在预测天气，不是说雨有自己的愿望。','助动词接古英语 willan／wyllan“想、愿意”，名词接古英语 willa“意愿、决心”。另有古英语 willian 这一与名词有关的动词，后来用于凭意志促成和以遗嘱留给。它们历史相关，现代句法却不同。',[['古英语相关形式：willan／wyllan；willa；willian','想、愿意；意愿、决心；通过意志决定'],['中古英语 willen；wille／wil 等','意愿表达与未来助动用法并存；名词也发展为书面身后安排'],['英语 will','助动词会、将；名词意志、遗嘱；普通动词用意志促成、遗赠']],'助动词 will 后接动词原形，可预测、承诺或临时决定。名词 a strong will 是坚定意志，a will 则可是一份写下身后财产安排的遗嘱。看清词性，才不会把每一个 will 都译成“将”。','will do；will not／won’t；against someone’s will；at will；make a will。','助动词的过去对应形式是 would；普通动词 will 的过去式可以是 willed。名词 will 的不同义也有可数性差别：意志常不可数，一份遗嘱可数。',('I will send you the revised file this afternoon.','我今天下午会把修改后的文件发给你。'),('The forecast says it will rain tonight.','天气预报说今晚会下雨。'),('She had the will to continue despite the setbacks.','尽管遭遇挫折，她仍有继续下去的决心。'),('He kept a copy of his will with the other important documents.','他把遗嘱副本和其他重要文件放在一起。'),sources=[S('will'),K('will'),O('will_3')]),
E('would','强读 /wʊd/；弱读 /wəd/、/əd/','会〔过去视角或假设〕；愿意；用以委婉表达','will 常从现在往后看；would 可以把镜头退到过去，或者移到想象中的情况。它也让请求与愿望不那么直截了当。','继承古英语 wolde，即 willan 的过去式、过去虚拟式，经中古英语 wolde 成为 would。现代的假设、委婉和过去习惯用法相互关联，但不能都硬译成“过去将会”。',[['古英语 willan；过去式、过去虚拟式 wolde','愿意；从过去或非直接现实的角度表达'],['中古英语 wolde → 英语 would','承接过去形式，发展并保留多种情态用法']],'He said he would come 是从他说话的过去时点看后来；I would help if… 是假设条件下会怎样。Would you…? 常用来客气请求；谈过去反复做的动作时，也可用 would。','would like to；would rather；would do if…；would have done；wouldn’t。','would 不等于每个句子都发生在过去。I would like a coffee 是现在的委婉愿望。谈过去的状态通常用 used to 更合适，别把 I used to know him 机械换为 would know。',('She said she would call after the meeting.','她说开完会后会打电话。'),('I would join you if I had more time.','如果时间更充裕，我会和你一起去。'),('Would you move your bag, please?','请把你的包挪一下，好吗？'),('Every summer, we would cycle to the lake after breakfast.','以前每到夏天，我们总会在早餐后骑车去湖边。'),sources=[S('would'),O('would'),K('would')]),
E('willing','/ˈwɪlɪŋ/','愿意的；乐于配合的','有人问“这件事你肯不肯做”，你愿意答应，就是 willing。它先说明意愿，不保证你已经具备能力或特别兴奋。','来自 will 表示意愿的动词分词；古英语有 willende 等相关形式，中古英语形成 willing 一类形式。现代可按 will 加 -ing 分析，但常作为形容词使用。',[['古英语 willan；相关分词 willende','愿意；带有意愿的'],['中古英语 willing 等 → 英语 willing','愿意行动、乐于配合的']],'be willing to do 最常用。a willing helper 是乐于帮忙的人。即使有顾虑，只要愿意尝试，也可以说 willing；不必把它翻成满腔热情。','be willing to try；a willing volunteer；ready and willing。','willing 说肯不肯，able 说能不能。eager 更突出迫不及待的积极心情，willing 可以只是愿意接受。',('I am willing to try a different approach.','我愿意试试另一种方法。'),('We found several willing volunteers to help move the chairs.','我们找到了几位乐意帮忙搬椅子的志愿者。'),sources=[S('willing'),K('willing'),O('willing')]),
E('willingly','/ˈwɪlɪŋli/','自愿地；乐意地','同样是留下来帮忙，有人被催着留下，有人自己爽快答应。后者的行动方式可以说 willingly。','willing 加副词 -ly；中古英语已有 willyngly 等形式，更早古英语也有相应的意愿副词形式。它描述做事时愿不愿意。',[['古英语相关 willendlīce；中古英语 willyngly','愿意地、主动地、乐意地等历史表达'],['英语 willingly〔可分析为 willing + -ly〕','自愿地、乐意地做某事']],'willingly give up a seat 是自愿让座；answer willingly 是愿意作答。它并不自动说明行动是否正确，只说明并非不情愿。','willingly accept；willingly share；give willingly；not willingly。','willingly 是乐意、自愿；wilfully 常是明知如此仍故意做，语气往往带批评。两词只差几个字母，评价却很不同。',('She willingly shared her notes with the new student.','她很乐意把笔记分享给新同学。'),('He accepted the extra responsibility willingly.','他自愿承担了这份额外责任。'),sources=[S('willing'),K('willingly'),O('willingly')]),
E('willingness','/ˈwɪlɪŋnəs/','意愿；乐于做某事的态度','讨论合作时，除了能力和资源，还要看双方有没有“肯一起做”的心态。这一部分就是 willingness。','willing 加 -ness，将愿意这一形容词性质变成名词；后面常用 to do 说明愿意做什么。',[['英语 willing','愿意的、乐于配合的'],['英语 willing + -ness → willingness','愿意做某事的意愿、态度']],'show a willingness to listen 是表现出愿意听取意见的态度。它可以成为合作的开端，但不代表事情已经真正完成。','a willingness to learn；show willingness；willingness to cooperate。','willingness 不是 ability，也不是已采取的 action。有意愿、能做到、实际做了，是三件可以分别讨论的事。',('Her willingness to learn mattered more than her lack of experience.','相比经验不足，她愿意学习的态度更重要。'),('Both sides expressed a willingness to continue the discussion.','双方都表示愿意继续讨论。'),sources=[K('willingness'),O('willingness')]),
E('unwilling','/ʌnˈwɪlɪŋ/','不愿意的；勉强的','别人提出一件事，你心里不想接受，甚至明确拒绝，就是 unwilling。障碍在意愿上，而不一定是做不到。','现代可拆否定 un- 加 willing。历史可接古英语 unwillende、中古英语 unwilland 后词尾变化，也有重新由 un-＋willing 构成的分析，不必假定只有一个新造时刻。',[['古英语 unwillende → 中古英语 unwilland；或后来 un-＋willing 重新构词','不愿意的旧形式与相同构词方式'],['英语 unwilling','不愿意、并非自愿的']],'unwilling to comment 是不愿发表评论；an unwilling participant 是不情愿的参与者。一个人最后做了某事，也仍可能从头到尾不愿意。','be unwilling to；an unwilling participant；unable or unwilling。','unwilling 强调不肯，unable 强调不能。reluctant 常更突出犹豫、勉强，unwilling 也可以表达明确的不愿。',('They were unwilling to share the unfinished report.','他们不愿分享尚未完成的报告。'),('He became an unwilling participant in the argument.','他不情愿地被卷进了这场争论。'),sources=[S('unwilling'),K('unwilling'),O('unwilling')]),
E('unwillingly','/ʌnˈwɪlɪŋli/','不情愿地；勉强地','脚已经朝门外走了，心里却不想去；这种“做了，但并不愿意”的状态，用 unwillingly 很合适。','可分析为 unwilling 加 -ly，也可从否定 un- 加 willingly 理解；都是英语内部对自愿程度的构词。',[['英语 unwilling；willingly 与否定 un-','不愿意的；自愿地及其否定'],['英语 unwillingly','带着不情愿而行动']],'常修饰答应、离开、交出或接受等动作。它说明当事人不愿意，未必表示有人用了强制手段。','agree unwillingly；leave unwillingly；hand over something unwillingly。','unwillingly 是不愿意；unknowingly 是不知情；unintentionally 是不是故意。三者不能因为都带否定前缀就互换。',('She agreed unwillingly to postpone the trip.','她不情愿地同意推迟旅行。'),('He left the lively discussion unwillingly when his train was due.','列车快到了，他不情愿地离开了热烈的讨论。'),sources=[K('unwillingly'),O('unwillingly')]),
E('unwillingness','/ʌnˈwɪlɪŋnəs/','不情愿；不愿意做某事的态度','谈判卡住，有时不是条件完全办不到，而是某一方不肯让步。unwillingness 把这份“不肯”作为原因拿出来说。','unwilling 加 -ness，构成表示态度、状态的名词。结构中的否定作用在 willing 上，不是否定名词后缀。',[['英语 unwilling','不愿意的'],['英语 unwilling + -ness → unwillingness','不愿意做某事的态度或状态']],'an unwillingness to change 指不愿改变；show unwillingness to cooperate 则说明缺少配合意愿。后面的 to do 能让“不愿意”具体落地。','unwillingness to change；an unwillingness to compromise；show unwillingness。','unwillingness 是意愿不足，inability 是能力或条件不足。判断原因时把这两者分开，句子的含义会差很多。',('Their unwillingness to compromise slowed the talks.','他们不愿妥协，使会谈进展缓慢。'),('His silence reflected uncertainty rather than an unwillingness to help.','他的沉默反映的是不确定，而非不愿帮忙。'),sources=[K('unwillingness'),O('unwillingness')]),
E('wilful','/ˈwɪlfəl/','任性的；执意的；故意的','明知道别人不同意，还是坚持“我就是要这样”，可以叫 wilful。说行为时，它又常强调事情是有意做出的。','will 名词加 -ful，中古英语已有 wilful 等形式。英国英语通常写 wilful，北美英语通常写 willful，含义和读音相同；不是两种程度不同的品质。',[['英语 will〔意愿、意志〕；-ful','自己的意愿；充满、具有'],['中古英语 wilful／willesful 等 → 英语 wilful／willful','按自己意愿坚持；又用于有意做出的行为']],'a wilful child 常说孩子任性，wilful damage 则说故意造成的损坏。前者评价性格，后者判断行为是否出于有意，通常都带负面语气。','a wilful child；wilful ignorance；wilful disregard。','willing 是愿意配合，wilful 往往是偏要按自己的意思来。determined 可以赞美坚定，wilful 更常带任性、执拗的批评。',('As a child, she was wilful and resisted every bedtime rule.','她小时候很任性，任何睡觉时间的规定都要反抗。'),('The review criticized his wilful disregard of the evidence.','评论批评他故意无视证据。'),sources=[S('willful'),S('wilful'),O('wilful'),K('wilful')]),
E('wilfully','/ˈwɪlfəli/','故意地；执意地；任性地','证据摆在眼前却偏要装作没看见，常说 wilfully ignored。它比普通“有意识地”更容易带责备意味。','现代按 wilful 加 -ly 分析；历史还有古英语 wilfullīce 一类相应副词。英国英语多写 wilfully，北美英语通常写 willfully，本条合并说明。',[['历史上与 will“意志”相连的副词形式，包括古英语 wilfullīce','按自己的意愿、故意等用法'],['英语 wilful + -ly → wilfully；亦拼 willfully','现代副词表示故意、任性或执意地']],'wilfully misunderstand 是故意曲解，不是单纯没听懂；wilfully blind 则形容不愿正视明显事实。它常暗含说话人认为这种选择不合理。','wilfully ignore；wilfully misinterpret；wilfully blind。','willingly 是心甘情愿，wilfully 常是明知仍故意，尤其是令人不赞同的做法。deliberately 的评价可以更中性。',('He wilfully misrepresented what she had said.','他故意歪曲了她说过的话。'),('The manager was accused of being wilfully blind to the warning signs.','经理被指责故意对警告迹象视而不见。'),sources=[O('wilfully'),K('wilfully'),S('wilful')]),
E('willed','/wɪld/','用意志促成了；以遗嘱留给了；有某种意志的','willed 在句子里可能很有力量：她用尽决心让自己继续走。也可能非常具体：某人把收藏通过遗嘱留给博物馆。先看后面的宾语。','普通动词 will 加 -ed，形成过去式、过去分词；它承接意志决定、遗赠等动词义。另有名词 will 加形容词性 -ed“具有某种意志”的构词，常出现在 strong-willed 等组合中。',[['古英语 willa；相关动词 willian → 英语普通动词 will','意志；凭意志决定，后来也有遗赠义'],['英语动词 will + -ed；另有名词 will + 形容词 -ed','过去式、分词；具有某种意志的描述']],'willed herself to continue 可以理解为靠意志让自己坚持；willed something to someone 是通过遗嘱把某物留给某人。词尾 -ed 在这里读 /d/，不额外增加一个音节。','willed himself to do；willed into existence；willed something to someone。','助动词 will 对应过去形式 would；willed 属于普通动词或形容词构词。不能把 She will come 的过去转述写成 She willed come。',('Exhausted, she willed herself to take one more step.','她筋疲力尽，仍用意志支撑自己再迈一步。'),('He willed his collection of maps to the local museum.','他通过遗嘱把收藏的地图留给了当地博物馆。'),sources=[S('will'),K('willed'),'https://www.merriam-webster.com/dictionary/willed']),
E('goodwill','/ˌɡʊdˈwɪl/','善意；友好合作的意愿；商誉','发生分歧时，对方仍愿意帮你、往好处理解你的做法，就是 goodwill。商店长期得到顾客的信任和好感，也与商业上的 goodwill 有关。','good 与名词 will“意愿”的组合，中古英语已有 good wille 等表达；更早的完整组合形式有重构分析，不当作已确证词形来画。后来发展出商业声誉与价值相关用法。',[['英语 good；will〔意愿〕','好；意愿、心意'],['中古英语 good wille → 英语 goodwill','善意、友好态度'],['英语 goodwill 的商业用法','企业与顾客的信任和声誉联系；也成为商誉术语']],'a gesture of goodwill 是表达善意的举动；customer goodwill 是顾客对企业积累的信任、好感。财务语境里的“商誉”是专门概念，不只是给公司评一个好名声分数。','a gesture of goodwill；build goodwill；customer goodwill；goodwill towards someone。通常不可数。','goodwill 说友好意愿与信任；willpower 说自我控制、坚持的力量。一个人很有毅力，不等于对别人有善意。',('They offered free repairs as a gesture of goodwill.','他们提出免费维修，以表达善意。'),('Years of reliable service had built strong customer goodwill.','多年来可靠的服务积累了顾客的信任和好感。'),sources=[K('goodwill'),O('goodwill')]),
E('welcome','/ˈwelkəm/','欢迎；受欢迎的；欢迎的表示','客人来了，你心里想的是“你来得正好，我很高兴”，这就是 welcome 的核心。它也能欢迎一种变化、建议或帮助，不限于迎接人。','古英语 wilcuma 表示合心意的来客，由 willa“愿望、意愿”与 cuma“来客”组成，cuma 接 cuman“来”。相关动词 wilcumian 也很早已有；后来 wil- 受 well 影响成为 wel-。现代不能简单把它解作“来得好”。',[['古英语 willa；cuma〔与 cuman“来”有关〕','愿望、意愿；来客'],['古英语 wilcuma／wilcumian → 中古英语 welcome／welcomen','合意的来客、欢迎；wel- 形式受到 well 影响'],['英语 welcome','欢迎人或事；受欢迎的；欢迎表示']],'We welcome feedback 是我们乐于接受反馈；You are welcome to join 是欢迎你加入。回应感谢的 You’re welcome 通常就是“不客气”，而不是再次邀请客人。','welcome someone to；a warm welcome；a welcome change；You’re welcome。','welcome 形容来的人或事受欢迎；welcoming 形容接待的人或地方让人感到受欢迎。The guest is welcome 与 The host is welcoming 角色不同。',('The team welcomed the new engineer warmly.','团队热情欢迎了新工程师。'),('The cooler weather was a welcome change.','天气转凉是一个令人欣喜的变化。'),('You are welcome to join us for lunch.','欢迎你和我们一起吃午饭。'),sources=[S('welcome'),K('welcome'),O('welcome_1')]),
E('welcoming','/ˈwelkəmɪŋ/','热情接待的；让人感到自在受欢迎的','你推开门，主人笑着招呼你，屋里也温暖舒适，就会觉得这里很 welcoming。它说的是环境或人的接纳感。','welcome 动词去词尾 e 加 -ing，既是现在分词，也形成形容词。来源仍接古英语的合意来客与欢迎动作，而不是新借入的外国词。',[['英语 welcome〔经古英语 wilcuma／wilcumian〕','欢迎、乐于接待'],['英语 welcome + -ing → welcoming','正在欢迎；能让人感到被接纳的']],'a welcoming smile 是迎接你的笑容；a welcoming atmosphere 是让人愿意走进来、待下去的氛围。用来形容地方时，是把人的接待感转到环境上。','welcoming staff；a welcoming smile；a welcoming atmosphere。','welcoming 多说主动接待的一方；welcome 说被乐意接受的人或事。a welcome guest 是受欢迎的客人，a welcoming host 是热情的主人。',('The volunteers created a welcoming atmosphere for newcomers.','志愿者为新来的人营造了亲切友好的氛围。'),('Soft lighting made the small café feel warm and welcoming.','柔和的灯光让这家小咖啡馆显得温暖而亲切。'),sources=[O('welcoming'),K('welcoming'),S('welcome')]),
E('unwelcome','/ʌnˈwelkəm/','不受欢迎的；不希望出现的','一件事来了，却不是你愿意迎接的：比如休息时的打扰，或者突然增加的费用，都可以叫 unwelcome。','否定 un- 加 welcome；中古英语早期已有相关形式。它否定的是人或事情受到欢迎的程度，而非说来客没有能力到达。',[['英语 welcome；否定 un-','受欢迎、令人高兴；不'],['中古英语起的 unwelcome → 现代英语 unwelcome','不受欢迎、并不希望发生的']],'an unwelcome guest 是不受欢迎的客人；an unwelcome surprise 是不愿碰到的意外。feeling unwelcome 是感觉自己未被接纳，并不必然意味着主人直接说了拒绝的话。','an unwelcome interruption；unwelcome attention；feel unwelcome。','unwelcome 说被接待的一方或出现的事不被希望；unwelcoming 则常形容接待者冷淡、地方缺乏亲切感。',('The extra charge came as an unwelcome surprise.','额外收费成了一个令人不快的意外。'),('No new student should feel unwelcome in the classroom.','任何新同学都不该在教室里感到不被接纳。'),sources=[S('unwelcome'),K('unwelcome'),O('unwelcome')]),
]
names=[w['word'] for w in W]+['willpower']
cat=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text()) if x['id']=='B3286')
EX={w:'按用户要求略过带连字符的词条。' for w in cat['family'] if '-' in w}
